-- FileMaker migration target schema: KarbonFM core CRM, SQLite (Tauri desktop app)
-- Written from the table, graph and value-list explorer CSVs (generated by gen04.py, then reviewed).
--
-- Evidence:
--   source implementation(s): karbon_data.fmp12 (all durable tables); karbon_kontacts.fmp12 and
--     karbon_kontroller.fmp12 hold only UI/session/transaction tables (no target tables, see appendix)
--   objects: objects/index.tsv (4,768 rows; DDR of 2026-10-27, FileMaker 26.0.3)
--   source data profile: none yet. Each install profiles its own export at import time (D-16, D-05)
--   target database/version: SQLite 3.45+ through rusqlite (bundled), WAL mode, PRAGMA foreign_keys = ON
--   timezone/DST decision: D-05 (local civil time of the user's machine, stored as ISO 8601 text, no offset)
--   unresolved blockers: none. OD-04-01 (foreign keys), OD-04-02 (money storage) and OD-04-03 (repeating fields) are
--     decided (owner, 2026-10-28).
--
-- Conventions (product decisions, 2026-10-27; owner decisions 2026-10-28):
--   * Names: snake_case of the FileMaker name (SKILL.md rule). Source names are kept in the appendix register.
--   * Types: Text -> TEXT, Number -> NUMERIC (money -> INTEGER cents, below), Date/Time/TimeStamp -> TEXT (ISO 8601),
--     Container -> TEXT holding the path of a file copied into the app data folder (owner, 2026-10-28; D-17); formerly the
--     SHA-256 of a file stored in the app data directory (D-17).
--   * Money (owner decision, 2026-10-28; OD-04-02): every money column is an INTEGER of cents (minor units, USD).
--     Arithmetic is in Rust on integers (i64); SQL SUM() over these columns is exact. Values are converted only at the
--     edges: the HTML layer parses and formats dollars (form parsing in the axum handlers, formatting in the askama templates), and the import converts the FileMaker decimal to cents, rounding half
--     away from zero as FileMaker Round() does (BR-IMPORT-01). Unit prices are cents too, so the source's 7-decimal
--     unit price is not kept (BR-SALES-01). The 22 money columns carry the comment "money: integer cents".
--   * Globals, summary fields, unstored calculations, JSON serializers and join anchors (ONE, z_xJoin) have no
--     column (appendix gives each a disposition). Secrets and PII listed in D-09 have no column.
--   * FileMaker "not empty" and "unique" validation is enforced in the command layer (07), not by NOT NULL/UNIQUE,
--     until the import profile of an install proves it (D-27, D-16). Only primary keys are NOT NULL.
--   * Primary keys: the UUID or serial key fields the table explorer proved (auto-enter UUID or serial, parent side of
--     Equal predicates). 1:1 subtype tables use the parent key (D-15).
--   * Foreign keys: enforced as constraints from day one (owner, 2026-10-28; OD-04-01): the fk_candidate = yes relationships plus 9
--     needs-profile ones. A pass on 2026-10-28 removed 6 primary-key references that pointed from a parent at its subtype
--     (activity -> call, activity_party -> activity_party_email, contact_method -> phone, party -> person, party_role -> lead,
--     sales_transaction -> sales_receipt), which made every parent insert fail, and 4 references on columns that hold ids of
--     several tables or a list. The import rejects a row whose parent is missing (BR-IMPORT-01).
--   * Repeating fields become child rows (owner, 2026-10-28; OD-04-03). The karbon_data tables have none (no maxRepetition > 1).
--   * A field with both a constant default and an auto-enter calculation takes the constant (owner, 2026-10-28; D-27).
--   * Hard-coded ids are seed rows plus Rust enums with the same ids (owner, 2026-10-28; D-19). Demo data: 04_demo_seed.sql.
--     ON DELETE is NO ACTION: deletes go through commands that remove children explicitly (07, D-08).
--   * Single user, no tenant column (D-35).
--   * QuickBooks Online is out of scope (owner, 2026-10-27; D-02): the karbon_LedgerLink mirror tables are not migrated and
--     the QBO sync-state columns (qbo_*, *sync*, item account refs) are dropped. A later integration links records through
--     external_link (external_link_type id 5 = QBO) behind the stub command accounting_integration_status (05 OP-INTEG-04).
--   * Twilio SMS/chat is out of scope (owner, 2026-10-28; OD-05-02, D-14): the Chat, ChatConsent and ChatMessage tables
--     and the system_setting Twilio columns are not migrated. activity.chat_ind and phone.sms_ind stay as data, so imported
--     SMS activities (activity_type 9) keep their activity row, without messages.
--   * Tax ids (organization.federal_tax_id_number, vendor.tax_id) are plain TEXT with no encryption, masking or extra
--     access rule (owner, 2026-10-28; demo data; D-09).

PRAGMA foreign_keys = ON;

BEGIN;

-- ---------------------------------------------------------------------------
-- Source-to-target mapping register: 04_database_schema_appendix.md
-- (one row per base table, field and relationship of karbon_data, kontacts and kontroller, and per value list)
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- App metadata and import lineage (target-platform requirement, D-34, D-40)
-- ---------------------------------------------------------------------------
CREATE TABLE app_meta (
  key TEXT PRIMARY KEY,           -- schema_version, created_at, imported_from_ddr_version
  value TEXT NOT NULL
);

CREATE TABLE import_batch (
  id TEXT PRIMARY KEY,            -- UUID of one import run
  started_at TEXT NOT NULL,       -- local civil time (D-05)
  finished_at TEXT,
  source_description TEXT,        -- export folder / file names chosen by the user
  status TEXT NOT NULL CHECK (status IN ('running', 'completed', 'failed')),
  report_path TEXT                -- rejected-row report (D-40)
);

CREATE TABLE import_rejected_row (
  batch_id TEXT NOT NULL REFERENCES import_batch(id),
  source_table TEXT NOT NULL,     -- FileMaker base table name
  source_key TEXT,                -- FileMaker Id of the row
  reason TEXT NOT NULL,
  raw_json TEXT                   -- the rejected row as exported
);

-- ---------------------------------------------------------------------------
-- Reference values (value lists). Custom value lists used by in-scope layouts are seeded here; lists built from
-- a field are queries (appendix, value-list register).
-- ---------------------------------------------------------------------------
CREATE TABLE value_list_item (
  list TEXT NOT NULL,             -- FileMaker value-list name
  value TEXT NOT NULL,
  sort_order INTEGER NOT NULL,
  PRIMARY KEY (list, value)
);

